messages.content:
Tool response:
Tool: find_auctions_nearby_new_york
Description: Find auctions within a specified radius of a given city/state.
Parameters:
    {
      "type": "object",
      "properties": {
        "city": {
          "type": "string",
          "description": "City name to search near",
          "title": "City"
        },
        "state": {
          "type": "string",
          "description": "State abbreviation to search near",
          "title": "State"
        },
        "radius_miles": {
          "type": "integer",
          "description": "Search radius in miles (default 50)",
          "default": 50,
          "title": "Radius Miles"
        }
      },
      "required": [
        "city",
        "state"
      ]
    }
